package io.github.syldegil.autotunnel;

import org.json.*;
import java.util.*;

/** Root journal codec. Operations are regenerated by the compiler, never deserialized as commands. */
final class NetworkCodec {
    static JSONObject snapshot(NetworkSnapshot s) throws Exception {
        JSONArray links = new JSONArray(), caps = new JSONArray();
        for (NetworkSnapshot.Link l : s.links) links.put(new JSONObject().put("name", l.name).put("index", l.ifindex)
            .put("role", l.role.name()).put("v4", l.v4).put("v6", l.v6));
        for (NetworkSnapshot.Capability c : s.capabilities) caps.put(c.name());
        return new JSONObject().put("boot", s.boot).put("generation", s.generation).put("at", s.sampledAt)
            .put("simulation", s.simulated).put("up", s.tunnelUp).put("links", links).put("capabilities", caps)
            .put("endpoint", s.endpoint).put("port", s.endpointPort).put("uid", s.vpnUid)
            .put("routes4", new JSONArray(s.routes4)).put("routes6", new JSONArray(s.routes6))
            .put("rules4", new JSONArray(s.rules4)).put("rules6", new JSONArray(s.rules6)).put("dns", new JSONArray(s.dns));
    }
    static NetworkSnapshot snapshot(JSONObject o) throws Exception {
        JSONArray array = o.getJSONArray("links"); if (array.length() > 128) throw new IllegalArgumentException();
        List<NetworkSnapshot.Link> links = new ArrayList<>();
        for (int i = 0; i < array.length(); i++) {
            JSONObject l = array.getJSONObject(i);
            links.add(new NetworkSnapshot.Link(l.getString("name"), l.getInt("index"), NetworkSnapshot.Role.valueOf(l.getString("role")), l.getString("v4"), l.getString("v6")));
        }
        EnumSet<NetworkSnapshot.Capability> caps = EnumSet.noneOf(NetworkSnapshot.Capability.class);
        for (String c : strings(o.getJSONArray("capabilities"))) caps.add(NetworkSnapshot.Capability.valueOf(c));
        return new NetworkSnapshot(o.getString("boot"), o.getString("generation"), o.getLong("at"), o.getBoolean("simulation"),
            o.getBoolean("up"), links, caps, o.getString("endpoint"), o.getInt("port"), o.getInt("uid"),
            strings(o.getJSONArray("routes4")), strings(o.getJSONArray("routes6")), strings(o.getJSONArray("rules4")),
            strings(o.getJSONArray("rules6")), strings(o.getJSONArray("dns")));
    }
    static List<String> strings(JSONArray a) throws Exception {
        if (a.length() > 4096) throw new IllegalArgumentException();
        List<String> out = new ArrayList<>(); for (int i = 0; i < a.length(); i++) out.add(a.getString(i)); return out;
    }
}
